if(!require(job)) install.packages("job")

job::job({
  install.packages(c("ggplot2", "tidyverse", "devtools", "BiocManager"))
})

channels_to_check <- colnames(Reordered_RENAMED_FLOWSET)[
  !colnames(Reordered_RENAMED_FLOWSET) %in% c("Time", "Event_length")
]

CLEANED_FLOWSET <- fsApply(Reordered_RENAMED_FLOWSET, function(x) {
  PeacoQC(
    ff               = x,
    channels         = channels_to_check,
    plot             = TRUE,
    save_fcs         = FALSE,
    output_directory = here("Outputs", "PeacoQC")
  )$FinalFF
})

ARCSINH_DOWNSAMPLED_CLEANED_FLOWSET <- fsApply(Reordered_DOWNSAMPLED_CLEANED_FLOWSET, function(x, cofactor = 5) {
  expr <- exprs(x)
  expr <- asinh(expr / cofactor)
  exprs(x) <- expr
  x
})
